import { Request, Response } from 'express';
import { PostService } from '../services/postService';

export class PostController {
  private postService: PostService;

  constructor(postService?: PostService) {
    this.postService = postService || new PostService();
  }

  public getPosts = async (req: Request, res: Response): Promise<void> => {
    try {
      const page = parseInt(req.query.page as string, 10) || 1;
      const limit = parseInt(req.query.limit as string, 10) || 10;
      const includeDrafts = req.query.includeDrafts === 'true';

      const result = await this.postService.getPosts(page, limit, includeDrafts);
      res.status(200).json(result);
    } catch (error: any) {
      res.status(500).json({ error: error.message || 'Internal server error' });
    }
  };

  public getPostById = async (req: Request, res: Response): Promise<void> => {
    try {
      const { id } = req.params;
      const post = await this.postService.getPostById(id);
      if (!post) {
        res.status(404).json({ error: 'Post not found' });
        return;
      }
      res.status(200).json(post);
    } catch (error: any) {
      res.status(500).json({ error: error.message || 'Internal server error' });
    }
  };

  public createPost = async (req: Request, res: Response): Promise<void> => {
    try {
      const { title, content, author, tags, isPublished } = req.body;
      if (!title || typeof title !== 'string' || !title.trim()) {
        res.status(400).json({ error: 'Title is required' });
        return;
      }
      if (!content || typeof content !== 'string' || !content.trim()) {
        res.status(400).json({ error: 'Content is required' });
        return;
      }

      const post = await this.postService.createPost({ title, content, author, tags, isPublished });
      res.status(201).json(post);
    } catch (error: any) {
      res.status(500).json({ error: error.message || 'Internal server error' });
    }
  };

  public updatePost = async (req: Request, res: Response): Promise<void> => {
    try {
      const { id } = req.params;
      const updatedPost = await this.postService.updatePost(id, req.body);
      if (!updatedPost) {
        res.status(404).json({ error: 'Post not found' });
        return;
      }
      res.status(200).json(updatedPost);
    } catch (error: any) {
      res.status(500).json({ error: error.message || 'Internal server error' });
    }
  };

  public deletePost = async (req: Request, res: Response): Promise<void> => {
    try {
      const { id } = req.params;
      const deleted = await this.postService.deletePost(id);
      if (!deleted) {
        res.status(404).json({ error: 'Post not found' });
        return;
      }
      res.status(204).send();
    } catch (error: any) {
      res.status(500).json({ error: error.message || 'Internal server error' });
    }
  };
}

export interface Post {
  id: string;
  title: string;
  content: string;
  author?: string;
  tags?: string[];
  isPublished: boolean;
  createdAt: Date;
  updatedAt: Date;
}

export class PostService {
  private posts: Map<string, Post> = new Map();

  public async getPosts(page: number = 1, limit: number = 10, includeDrafts: boolean = false): Promise<{ posts: Post[]; total: number; page: number; limit: number }> {
    const allPosts = Array.from(this.posts.values());
    const filteredPosts = includeDrafts ? allPosts : allPosts.filter(p => p.isPublished);

    const pageNum = Math.max(1, page);
    const limitNum = Math.max(1, limit);
    const skip = (pageNum - 1) * limitNum;

    const paginatedPosts = filteredPosts.slice(skip, skip + limitNum);
    return {
      posts: paginatedPosts,
      total: filteredPosts.length,
      page: pageNum,
      limit: limitNum,
    };
  }

  public async getPostById(id: string): Promise<Post | null> {
    return this.posts.get(id) || null;
  }

  public async createPost(data: { title: string; content: string; author?: string; tags?: string[]; isPublished?: boolean }): Promise<Post> {
    const id = Math.random().toString(36).substring(2, 9);
    const newPost: Post = {
      id,
      title: data.title.trim(),
      content: data.content.trim(),
      author: data.author || 'Anonymous',
      tags: data.tags || [],
      isPublished: data.isPublished ?? false,
      createdAt: new Date(),
      updatedAt: new Date(),
    };
    this.posts.set(id, newPost);
    return newPost;
  }

  public async updatePost(id: string, data: Partial<Omit<Post, 'id' | 'createdAt'>>): Promise<Post | null> {
    const post = this.posts.get(id);
    if (!post) {
      return null;
    }
    const updatedPost: Post = {
      ...post,
      ...data,
      updatedAt: new Date(),
    };
    this.posts.set(id, updatedPost);
    return updatedPost;
  }

  public async deletePost(id: string): Promise<boolean> {
    if (!this.posts.has(id)) {
      return false;
    }
    return this.posts.delete(id);
  }
}

export interface CreatePostDto { title: string; content: string; tags?: string[]; authorId: string; }
export class PostService {
  static createPost(data: CreatePostDto) {
    if (!data.title || data.title.trim() === '') {
      throw new Error('Title is required');
    }
    if (!data.content || data.content.trim() === '') {
      throw new Error('Content is required');
    }
    return {
      id: Date.now().toString(),
      title: data.title.trim(),
      content: data.content.trim(),
      tags: data.tags || [],
      authorId: data.authorId,
      createdAt: new Date().toISOString()
    };
  }
}

import { Request, Response, NextFunction } from 'express';
export const authenticate = (req: Request, res: Response, next: NextFunction) => {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Unauthorized: Missing or invalid token' });
  }
  const token = authHeader.split(' ')[1];
  if (token !== 'valid-secret-token') {
    return res.status(401).json({ error: 'Unauthorized: Invalid token' });
  }
  next();
};

